 try{const raw=localStorage.getItem('moldae-draft-v2:'+id);if(raw){const saved=JSON.parse(raw);if(saved.template?.id===id){saved.template.document=repairTextFields(saved.template.document);validateDocument(saved.template.document);const content=t=>JSON.stringify({title:t.title,theme:t.theme,source_note:t.source_note,document:validateDocument(t.document)});if(content(saved.template)===content(S.data.template))localStorage.removeItem('moldae-draft-v2:'+id);else S.recovery=saved;}}}catch{feedback('Não foi possível ler a recuperação local.',true);}
