async function installGarden(){
 const existing=(await request('templates'+(S.showDeleted?'?deleted=1':S.showArchived?'?archived=1':''))).templates;
 for(const [key,preset] of Object.entries(GARDEN_PRESETS)){
  const marker='garden-layered-v2:'+key;
  if(existing.some(t=>t.source_note?.startsWith(marker+' · pronto')))continue;
  feedback('Preparando '+preset.title+'…');
  let data;const partial=existing.find(t=>t.source_note===marker+' · importando')||existing.find(t=>t.source_note?.startsWith('garden-layered-v1:'+key+' · pronto')&&t.revision===2);
  if(partial)data=await request('templates/'+partial.id);
  else data=await request('templates',{method:'POST',body:JSON.stringify({title:preset.title,theme:'Jardim Encantado',source_note:marker+' · importando',document:{schema:1,structure:'art-a4',background:'#ffffff',images:[],fields:[]}})});
  const t=data.template,keys=Object.fromEntries(Object.keys(GARDEN_ASSETS).map(k=>[k,k])),draft=gardenDocument(key,keys),used=[...new Set(draft.images.map(i=>i.asset))],assetIds={};
  for(const name of used){
   const filename=GARDEN_ASSETS[name]+'.png',old=data.assets.find(a=>a.filename===filename);
   if(old){assetIds[name]=old.id;continue;}
   const response=await fetch('/assets/jardim-camadas/'+filename);if(!response.ok)throw new Error('Não foi possível carregar '+filename+'. Tente adicionar os modelos novamente.');
   const form=new FormData();form.set('file',new File([await response.blob()],filename,{type:'image/png'}));
   const uploaded=await request('templates/'+t.id+'/assets',{method:'POST',body:form});assetIds[name]=uploaded.asset_id;
  }
  const document=gardenDocument(key,assetIds);if(key==='cake'){await loadFonts();const result=await generateContour(document,{name:'Sophia',age:'1 aninho'},id=>'/api/admin/studio/assets/'+id,{margin:2});document.paths=[...result.paths,...document.paths];document.order=[...result.paths.map(p=>p.id),...document.order];}
  await request('templates/'+t.id,{method:'PATCH',body:JSON.stringify({...t,source_note:marker+' · pronto · '+preset.note+'. Referência: Kit Jardim Encantado. Flores, casinhas, fada e borboleta são PNGs independentes; contornos e textos são editáveis. Faça prova de impressão.',document})});
 }
 S.list=null;S.error='';render();toast('Os quatro modelos em camadas foram adicionados ao Estúdio.');
}

