function organizedTemplates(){const list=filterTemplates(S.list||[],studioFilters),models=groupLibraryModels(list),groups=renderLibraryGroups(models,{...libraryViewState,renderCard:libraryArtworkCard});const themes=[...new Set((S.list||[]).map(t=>t.theme).filter(Boolean))].sort();return `<div class="studio-library"><div class="studio-intro"><span class="eyebrow">SEU ATELIÊ DIGITAL</span><h2>Biblioteca de moldes</h2><p>Escolha o tipo de molde, depois o formato e a arte. Cada formato pode ter vários temas, com medidas e cortes preservados.</p></div><div id="studio-feedback" role="status"></div>${S.error?`<p role="alert">${esc(S.error)}</p>`:''}<section class="manage-card"><div class="manage-toolbar studio-library-actions"><a class="btn-primary" href="#/admin/estudio/nova-arte">+ Criar nova arte</a><button class="btn-outline" data-studio="create-kit">Montar kit de moldes</button><details class="studio-menu" name="studio-quick-menu"><summary>Organizar biblioteca</summary><div class="studio-menu-content"><button data-studio="toggle-deleted">${S.showDeleted?'Voltar aos moldes':'Abrir lixeira'}</button><button data-studio="toggle-archived">${S.showArchived?'Mostrar moldes em uso':'Ver arquivados'}</button><button data-studio="reload">Atualizar biblioteca</button></div></details><span class="studio-library-status">${S.showDeleted?'Lixeira':S.showArchived?'Incluindo arquivados':'Moldes em uso'}</span></div><form id="studio-library-filter" class="studio-library-filter"><label>Buscar molde ou variação<input name="search" value="${esc(studioFilters.search)}" placeholder="Ex.: Milk, horizontal, 2 folhas"></label><label>Tipo de molde<select name="family"><option value="">Todos os tipos</option>${Object.entries(MOLD_FAMILIES).map(([id,label])=>option(id,label,studioFilters.family)).join('')}</select></label><label>Tema<select name="theme"><option value="">Todos os temas</option>${themes.map(t=>option(t,t,studioFilters.theme)).join('')}</select></label><button class="btn-outline">Filtrar</button><button type="button" class="btn-outline" data-studio="clear-filters">Limpar</button></form><p>${list.length} molde(s) encontrado(s). Tipo é o produto (ex.: Tag retangular). Formato é seu desenho e tamanho. Tema é a decoração aplicada.</p><details class="studio-library-advanced"><summary>Adicionar modelos prontos do sistema</summary><p>Esta seção adiciona modelos prontos que acompanham o Moldaê, como os modelos Bosque abaixo. Não importa arquivos do seu computador. Para criar um novo tema com um molde que você já tem, use “Criar nova arte”.</p><button class="btn-outline" data-studio="cachepot-install">Adicionar cachepô Bosque · 2 partes</button><button class="btn-outline" data-studio="bosque-install">Tag plana Bosque · artes 3D</button><button class="btn-outline" data-studio="bosque-brigadeiro-install">Adicionar forminha coração Bosque</button><button class="btn-outline" data-studio="bosque-folded-install">Adicionar tag dobrável Bosque</button>${woodlandGallery(false)}</details>${groups||'<p>Nenhum molde encontrado com esses filtros.</p>'}</section><details class="manage-card"><summary>Criar uma estrutura de molde do zero · avançado</summary><div class="studio-start">${Object.entries(STRUCTURES).map(([k,v])=>`<button class="studio-structure" data-studio-new="${k}"><strong>${esc(v.label)}</strong><small>${esc(v.note)}</small><b>Criar estrutura</b></button>`).join('')}</div></details>`}
function catalogControls(t){const c=classifyTemplate({...t,structure:t.document.structure,catalog:t.document.catalog});return `${c.baseModel==='bosque-brigadeiro-coracao-35-v2'?heartMoldPreview():''}${c.baseModel==='tag-mesa-dobravel-90x35-v1'?'<details class="studio-mockup"><summary>Ver simulação montada em 3D</summary><img src="/assets/bosque-camadas/tag-produto-v2.png" alt="Simulação ilustrativa da tag dobrável com duas faces e vinco no topo"><small>Apresentação ilustrativa. O relevo é visual, impresso na arte.</small></details>':''}<fieldset class="studio-catalog-controls"><legend>Organização e variações</legend>${select('Tipo de molde','catalog-family',Object.entries(MOLD_FAMILIES).map(([id,label])=>option(id,label,c.family)).join(''))}${field('Nome do formato (sem tema ou personagem)','catalog-modelName',c.modelName||'','text','maxlength="100" placeholder="Ex.: Retangular com cantos arredondados"')}${field('Descrição desta arte','catalog-variant',c.variant,'text','maxlength="100"')}${field('Tamanho / impressão','catalog-size',c.size,'text','maxlength="100"')}${field('Identificador do modelo-base','catalog-baseModel',c.baseModel,'text','maxlength="100"')}<small>Tipo identifica o produto; nome do formato identifica o desenho; tamanho descreve as medidas. O tema fica separado. Formatos com cortes ou medidas diferentes ficam em grupos próprios, mesmo com referência igual.</small></fieldset>`}
async function installBosque(key='flat'){
 const sweet=key==='brigadeiro',folded=key==='folded',marker=sweet?'bosque-brigadeiro-coracao-v2':folded?'bosque-folded-tag-v1':'bosque-horizontal-tag-v2',list=(await request('templates')).templates,ready=list.find(t=>t.source_note?.startsWith(marker+' · pronto'));
 if(ready){location.hash='/admin/estudio/'+ready.id;return}
 const previous=list.find(t=>t.source_note===marker+' · importando')||(!folded&&!sweet&&list.find(t=>t.source_note?.startsWith('bosque-horizontal-tag-v1')));
 let data=previous?await request('templates/'+previous.id):await request('templates',{method:'POST',body:JSON.stringify({title:sweet?'Forminha de brigadeiro coração · Bosque Encantado':folded?'Tag dobrável de mesa · ursinho 3D · Bosque Encantado':'Tag plana horizontal · ursinho 3D · Bosque Encantado',theme:'Bosque Encantado',source_note:marker+' · importando',document:{schema:1,structure:'art-a4',background:'#ffffff',images:[],fields:[]}})});
 const ids={};for(const [key,filename]of Object.entries(BOSQUE_3D_ASSETS)){const old=data.assets.find(a=>a.filename===filename);if(old){ids[key]=old.id;continue}feedback('Adicionando '+filename+'…');const r=await fetch('/assets/bosque-camadas/'+filename);if(!r.ok)throw new Error('Não foi possível carregar a arte.');const form=new FormData();form.set('file',new File([await r.blob()],filename,{type:'image/png'}));ids[key]=(await request('templates/'+data.template.id+'/assets',{method:'POST',body:form})).asset_id}
 let document=sweet?bosqueBrigadeiroDocument(ids):folded?bosqueFoldedTagDocument(ids):bosqueTagDocument(ids);
 if(previous&&!folded&&!sweet&&data.template.document.images.length){document=structuredClone(data.template.document);for(const l of document.images){const a=data.assets.find(a=>a.id===l.asset);for(const [key,filename]of Object.entries(BOSQUE_ASSETS))if(a?.filename===filename)l.asset=ids[key]}document.catalog={...document.catalog,family:'tag',variant:'Plana horizontal · ursinho 3D'};}
 const result=await request('templates/'+data.template.id,{method:'PATCH',body:JSON.stringify({...data.template,document,source_note:marker+' · pronto · '+(sweet?'Forminha com topo coração de duas curvas por face, mesmo fundo quadrado, recortes e abas de cola do primeiro modelo. Protótipo para prova física.':folded?'Duas faces de 90 × 35 mm, aberta 90 × 70 mm; vinco central, costas em sentido oposto. Não cortar no meio.':'Variação plana preservada, artes atualizadas com sombreamento 3D sem alterar as posições.')+' Ursinho e folhagem em PNGs independentes; contorno, fundo, bordas e textos editáveis. Medidas propostas; conferir prova de impressão.'})});
 S.list=null;S.data=null;location.hash='/admin/estudio/'+result.template.id;toast(sweet?'Forminha Bosque adicionada ao Estúdio.':folded?'Tag dobrável criada com duas faces e vinco central.':'Tag plana preservada e artes 3D atualizadas.');
}
