function shadowControls(l){const s=l.shadow||{dx:1,dy:1,blur:.7,color:'#49301f',opacity:.3};return `<fieldset class="studio-catalog-controls"><legend>Sombra editável da imagem</legend>${select('Sombra','shadow-enabled',option('off','Sem sombra',l.shadow?'on':'off')+option('on','Ativar sombra',l.shadow?'on':'off'))}${l.shadow?field('Deslocamento X (mm)','shadow-dx',s.dx,'number','min="-15" max="15" step="0.1"')+field('Deslocamento Y (mm)','shadow-dy',s.dy,'number','min="-15" max="15" step="0.1"')+field('Suavidade (mm)','shadow-blur',s.blur,'number','min="0" max="8" step="0.1"')+field('Intensidade (0 a 1)','shadow-opacity',s.opacity,'number','min="0" max="1" step="0.05"')+field('Cor da sombra','shadow-color',s.color,'color'):''}<small>Acompanha o contorno transparente do PNG. Use PNG de até 4 megapixels. PNG/JPG sem transparência projetam a sombra da imagem inteira; o PDF exporta sombras de PNG.</small></fieldset>`}
function imageShadowSVG(l,source,rotation){if(!l.shadow?.opacity)return '';const s=l.shadow,id='shadow-'+l.id;return `<defs><filter id="${id}" x="-100%" y="-100%" width="300%" height="300%" color-interpolation-filters="sRGB"><feGaussianBlur in="SourceAlpha" stdDeviation="${s.blur}" result="blur"/><feOffset in="blur" dx="${s.dx}" dy="${s.dy}" result="offset"/><feFlood flood-color="${s.color}" flood-opacity="${s.opacity}" result="color"/><feComposite in="color" in2="offset" operator="in"/></filter></defs><g clip-path="url(#clip-${l.face})"><g transform="${rotation}"><g filter="url(#${id})" pointer-events="none"><svg x="${l.x}" y="${l.y}" width="${l.w}" height="${l.h}" viewBox="${l.x} ${l.y} ${l.w} ${l.h}" overflow="hidden"><image x="${source.x}" y="${source.y}" width="${source.w}" height="${source.h}" opacity="${l.opacity??1}" href="/api/admin/studio/assets/${l.asset}" preserveAspectRatio="none"/></svg></g></g></g>`}

function woodlandGallery(editing){return `<details class="manage-card" ${editing?'':'open'}><summary>Forminhas Bosque · escolher arte</summary><p>Mesmo molde coração. Escolha um bichinho para ${editing?'aplicar neste rascunho (substitui a composição; Ctrl+Z desfaz)':'abrir seu modelo editável'}. Personagem, folhagens, fundo e listras ficam separados.</p><div class="studio-assets">${WOODLAND_MODELS.map(m=>`<button data-woodland="${m.id}" data-woodland-apply="${editing?'1':'0'}"><img src="/assets/bosque-camadas/${m.filename}" alt="${m.label}" loading="lazy"><strong>${m.label}</strong><small>${editing?'Aplicar arte ao molde':'Abrir modelo para editar'}</small></button>`).join('')}</div></details>`}
async function openWoodland(id,apply){
 const model=WOODLAND_MODELS.find(m=>m.id===id);if(!model)return;
 if(apply&&S.data?.template.document.structure!=='brigadeiro-petal')return;
 const marker='bosque-woodland-'+id+'-v1';let data;
 if(apply){await save();data=S.data}else{
 const list=(await request('templates')).templates,existing=list.find(t=>t.source_note?.startsWith(marker+' · pronto'));
 if(existing){location.hash='/admin/estudio/'+existing.id;return}
 const partial=list.find(t=>t.source_note===marker+' · importando');
 data=partial?await request('templates/'+partial.id):await request('templates',{method:'POST',body:JSON.stringify({title:'Forminha coração · '+model.label+' · Bosque',theme:'Bosque Encantado',source_note:marker+' · importando',document:{schema:1,structure:'art-a4',background:'#ffffff',images:[],fields:[]}})});
 }
 const ids={};for(const [key,filename]of Object.entries({character:model.filename,leaves:'folhagem.png'})){
 const old=data.assets.find(a=>a.filename===filename);if(old){ids[key]=old.id;continue}
 const response=await fetch('/assets/bosque-camadas/'+filename);if(!response.ok)throw new Error('Arte indisponível: '+filename);
 const form=new FormData();form.set('file',new File([await response.blob()],filename,{type:'image/png'}));ids[key]=(await request('templates/'+data.template.id+'/assets',{method:'POST',body:form})).asset_id;
 }
 if(apply){const fresh=await request('templates/'+data.template.id);S.data.assets=fresh.assets;S.data.template.document=woodlandDocument(model,ids,S.data.template.document.dimensions);S.selected=null;S.selection=[];dirty();await save();render();feedback('Arte aplicada em camadas. Ctrl+Z desfaz.');return}
 await request('templates/'+data.template.id,{method:'PATCH',body:JSON.stringify({...data.template,document:woodlandDocument(model,ids),source_note:marker+' · pronto · Arte em camadas independentes; recorte coração preservado. Conferir montagem física.'})});S.list=null;location.hash='/admin/estudio/'+data.template.id;
}
document.addEventListener('click',e=>{const button=e.target.closest('[data-woodland]');if(button)busy(()=>openWoodland(button.dataset.woodland,button.dataset.woodlandApply==='1'))});

let elementQuery='',elementColor='#d2944c',elementColorTarget='fill';
let recentElements=[];try{const saved=JSON.parse(localStorage.getItem('moldae-recent-elements')||'[]');if(Array.isArray(saved))recentElements=saved.filter(id=>ELEMENTS.some(e=>e.id===id)).slice(0,8);}catch{}
function elementGroups(){
 const norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),query=norm(elementQuery.trim()),matching=ELEMENTS.filter(e=>norm(e.label+' '+e.category).includes(query));
 const grid=list=>'<div class="studio-elements-grid">'+list.map(e=>`<button type="button" data-element-shape="${e.id}" title="${e.label}" aria-label="Adicionar ${e.label}">${elementIcon(e)}<span>${e.label}</span></button>`).join('')+'</div>';
 const recent=!query?recentElements.map(id=>ELEMENTS.find(e=>e.id===id)).filter(Boolean):[];
 return (recent.length?'<section><h4>Usados recentemente</h4>'+grid(recent)+'</section>':'')+[...new Set(matching.map(e=>e.category))].map(category=>'<section><h4>'+category+'</h4>'+grid(matching.filter(e=>e.category===category))+'</section>').join('')+(!matching.length?'<p class="studio-hint">Nenhuma forma encontrada. Tente círculo, estrela ou seta.</p>':'');
}
function elementsPanel(){return `<div class="studio-elements-search"><span aria-hidden="true">⌕</span><input type="search" data-element-search aria-label="Buscar elementos" placeholder="Buscar elementos" value="${esc(elementQuery)}"></div><div class="studio-elements-colors"><strong>Cores</strong><label>Aplicar em<select data-element-color-target><option value="fill" ${elementColorTarget==='fill'?'selected':''}>Preenchimento</option><option value="color" ${elementColorTarget==='color'?'selected':''}>Contorno / linha</option></select></label><div class="studio-element-swatches">${ELEMENT_COLORS.map(c=>`<button type="button" data-element-color="${c}" style="--swatch:${c}" aria-label="Cor ${c}" title="${c}"></button>`).join('')}<label class="studio-element-custom" title="Escolher outra cor">+<input type="color" data-element-custom-color aria-label="Cor personalizada" value="${elementColor}"></label></div><small id="studio-element-color-hint">Escolha uma cor e clique em uma forma para adicionar.</small></div><div id="studio-element-groups">${elementGroups()}</div><p class="studio-hint">Clique para inserir. Arraste, redimensione e gire na folha. Em Posição você ajusta transparência, cantos e espelhamento.</p>`;}
function refreshElementColors(){const l=current(),input=document.querySelector('[data-element-custom-color]'),hint=document.querySelector('#studio-element-color-hint');const color=l?.kind?(l.kind==='line'||l.kind==='curve'?l.color:l[elementColorTarget]||elementColor):elementColor;if(input)input.value=color;document.querySelectorAll('[data-element-color]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.elementColor.toLowerCase()===color.toLowerCase())));if(hint)hint.textContent=l?.kind?'Cor aplicada à forma selecionada.':'Escolha uma cor e clique em uma forma para adicionar.';}
function applyElementColor(color){if(S.busy||!/^#[0-9a-f]{6}$/i.test(color))return;elementColor=color;const l=current();if(l?.kind){if(l.locked){feedback('Desbloqueie a forma para alterar sua cor.',true);return;}if(selectionIds().length>1){feedback('Selecione uma forma por vez para alterar sua cor.',true);return;}const key=['line','curve','rect'].includes(l.kind)?'color':elementColorTarget;l[key]=color;dirty();properties();preview();}refreshElementColors();}
