function changeZoom(value,fit=false){if(!S.data)return;S.fitPage=fit;if(!fit){S.zoom=clampZoom(value);const l=current();try{const b=l?.asset?selectionBounds(S.data.template.document,[l.id]):printBounds(S.data.template.document);zoomFocus={x:b.x+b.w/2,y:b.y+b.h/2};}catch{zoomFocus=null;}}else zoomFocus=null;preview();}
function layoutCanvasZoom(spec,ruler,viewport,sheet){const stage=viewport?.querySelector('.studio-canvas-stage');if(!stage)return;const first=!stage.dataset.zoomReady,layout=zoomLayout({width:spec.width,height:spec.height,ruler,zoom:S.zoom,viewportWidth:viewport.clientWidth,viewportHeight:viewport.clientHeight,focus:S.fitPage?null:zoomFocus});sheet.style.width=layout.sheetWidth+'px';sheet.style.left=layout.left+'px';sheet.style.top=layout.top+'px';stage.style.width=layout.stageWidth+'px';stage.style.height=layout.stageHeight+'px';if(zoomFocus||S.fitPage||first){viewport.scrollLeft=layout.scrollLeft;viewport.scrollTop=layout.scrollTop;}stage.dataset.zoomReady='true';zoomFocus=null;}
