function faceLinkControls(d,groupId){const groups=faceLinkGroups(d);if(!groups.length)return '';const active=d.faceLinks,group=groups.find(g=>g.id===groupId)||groups.find(g=>active&&active.areas.every(id=>g.areas.some(a=>a.id===id)))||groups[0],selected=active?.areas||group.areas.map(a=>a.id),source=active?.source&&group.areas.some(a=>a.id===active.source)?active.source:group.areas[0].id;return `<fieldset class="studio-catalog-controls" id="studio-face-links"><legend>Editar faces em conjunto</legend><p class="studio-hint">${active?'Vinculado: editar em qualquer face atualiza as demais selecionadas.':'Independente: as alterações ficam somente na face editada.'}</p><label>Conjunto de faces<select id="face-link-group">${groups.map(g=>option(g.id,g.label,group.id)).join('')}</select></label><label>Face de origem<select id="face-link-source">${group.areas.map(a=>option(a.id,a.label,source)).join('')}</select></label><div class="studio-link-targets">${group.areas.map(a=>`<label><input type="checkbox" data-link-target="${a.id}" ${selected.includes(a.id)?'checked':''}>${esc(a.label)}</label>`).join('')}</div><p class="studio-hint">Ao vincular, a composição da origem substitui as artes nas outras faces marcadas. Posição e rotação acompanham o ângulo de cada face; corte, vinco e abas são preservados. Ctrl+Z desfaz.</p><button data-studio="copy-face-once">Aplicar às demais faces · cópia independente</button><button data-studio="apply-face-links">Vincular e copiar a face de origem</button>${active?'<button data-studio="detach-face-links">Editar faces separadamente</button>':''}</fieldset>`;}
function applyFaceLinks(independent=false){try{const source=document.querySelector('#face-link-source').value,ids=[...document.querySelectorAll('[data-link-target]:checked')].map(el=>el.dataset.linkTarget);if(!ids.includes(source))ids.unshift(source);S.data.template.document=replicateFaces(S.data.template.document,source,ids);if(independent)delete S.data.template.document.faceLinks;dirty();properties();render();feedback(independent?'Composição copiada. As faces podem ser editadas separadamente.':'Faces vinculadas: posição e ângulo sincronizados.');}catch(error){feedback(error.message,true);}}
