document.addEventListener('submit',e=>{if(e.target.id!=='studio-new-art')return;e.preventDefault();const f=new FormData(e.target);busy(async()=>{const source=await request('templates/'+encodeURIComponent(f.get('source')));const result=await request('templates/'+source.template.id+'/clone',{method:'POST',body:JSON.stringify({revision:source.template.revision,title:f.get('title'),theme:f.get('theme'),mode:f.get('mode'),classification_required:true})});S.list=null;S.error='';location.hash='/admin/estudio/'+result.template.id;});});

document.addEventListener('click',e=>{if(!e.target.closest('[data-studio="cachepot-install"]'))return;busy(async()=>{
 const {cachepotDocument}=await import('./studio-cachepot.mjs');const all=(await request('templates')).templates;let first;
 for(const part of [1,2]){const marker='cachepot-bosque-canva-p'+part+'-v1';let entry=all.find(t=>t.source_note?.startsWith(marker));let data=entry?await request('templates/'+entry.id):await request('templates',{method:'POST',body:JSON.stringify({title:'Cachepô Bosque Encantado · parte '+part+' de 2',theme:'Bosque Encantado',source_note:marker+' · importando',document:cachepotDocument(part)})});first??=data.template.id;if(data.template.source_note.includes(' · pronto'))continue;
 const ids={};for(const [key,filename]of Object.entries({character:'bosque-bear-v1.png',leaves:'folhagem-3d-v2.png'})){const old=data.assets.find(a=>a.filename===filename);if(old){ids[key]=old.id;continue}const response=await fetch('/assets/bosque-camadas/'+filename);if(!response.ok)throw new Error('Arte do Bosque indisponível.');const form=new FormData();form.set('file',new File([await response.blob()],filename,{type:'image/png'}));ids[key]=(await request('templates/'+data.template.id+'/assets',{method:'POST',body:form})).asset_id;}
 await request('templates/'+data.template.id,{method:'PATCH',body:JSON.stringify({...data.template,document:cachepotDocument(part,ids),source_note:marker+' · pronto · Canva DAHaQQlt0NI páginas 379/380. Reconstrução do contorno visível, duas partes complementares. Validar medidas e montagem em papel antes de comercializar.'})});}
 S.list=null;location.hash='/admin/estudio/'+first;
});});

// Two fingers navigate the canvas without resizing or moving artwork.
const canvasTouches=new Map();let pinch=null,pinchFinishing=false;
const touchPair=()=>[...canvasTouches.values()].slice(0,2);
const touchMid=points=>({x:(points[0].x+points[1].x)/2,y:(points[0].y+points[1].y)/2});
const touchDistance=points=>Math.hypot(points[0].x-points[1].x,points[0].y-points[1].y);
document.addEventListener('pointerdown',e=>{
 if(e.pointerType!=='touch'||S.busy||!S.data||!e.target.closest('.studio-canvas-scroll'))return;
 const viewport=e.target.closest('.studio-canvas-scroll');canvasTouches.set(e.pointerId,{x:e.clientX,y:e.clientY});
 if(canvasTouches.size<2&&!pinchFinishing)return;
 e.preventDefault();e.stopImmediatePropagation();viewport.setPointerCapture(e.pointerId);
 if(canvasTouches.size!==2||pinchFinishing)return;
 // Stop every one-finger editing gesture before changing the view.
 drag=null;marqueeDrag=null;geoDrag=null;canvasPan=null;S.marquee=null;S.historyGroup=null;S.snapHit=null;
 const points=touchPair(),mid=touchMid(points),sheet=document.querySelector('#studio-sheet'),rect=sheet.getBoundingClientRect();
 pinch={viewport,startZoom:S.zoom,startDistance:touchDistance(points),anchor:{x:(mid.x-rect.left)/(2.5*S.zoom),y:(mid.y-rect.top)/(2.5*S.zoom)}};
 S.fitPage=false;zoomFocus=null;preview();
},true);
document.addEventListener('pointermove',e=>{
 if(!canvasTouches.has(e.pointerId))return;
 canvasTouches.set(e.pointerId,{x:e.clientX,y:e.clientY});
 if(!pinch&&!pinchFinishing)return;e.preventDefault();e.stopImmediatePropagation();
 if(!pinch||canvasTouches.size<2)return;
 const p=pinch,points=touchPair(),mid=touchMid(points),rect=p.viewport.getBoundingClientRect();
 const next=pinchZoom({...p,distance:touchDistance(points),midpoint:{x:mid.x-rect.left,y:mid.y-rect.top},viewportWidth:p.viewport.clientWidth,viewportHeight:p.viewport.clientHeight});
 S.zoom=next.zoom;preview();p.viewport.scrollLeft=next.scrollLeft;p.viewport.scrollTop=next.scrollTop;
}, {capture:true,passive:false});
for(const type of ['pointerup','pointercancel'])document.addEventListener(type,e=>{
 if(!canvasTouches.has(e.pointerId))return;canvasTouches.delete(e.pointerId);
 if(pinch||pinchFinishing){e.preventDefault();e.stopImmediatePropagation();if(canvasTouches.size<2){pinch=null;pinchFinishing=canvasTouches.size>0;}if(!canvasTouches.size)pinchFinishing=false;}
},true);
window.addEventListener('blur',()=>{canvasTouches.clear();pinch=null;pinchFinishing=false;canvasPan=null;});

// Keep navigation separate from artwork manipulation; capture on the stable viewport.
let canvasPan=null;
document.addEventListener('pointerdown',e=>{
 const viewport=e.target.closest('.studio-canvas-scroll');
 if(!viewport||S.tool!=='pan'||S.busy||e.button>0)return;
 canvasPan={id:e.pointerId,x:e.clientX,y:e.clientY,left:viewport.scrollLeft,top:viewport.scrollTop,viewport};
 viewport.setPointerCapture(e.pointerId);e.preventDefault();e.stopImmediatePropagation();
},true);
document.addEventListener('pointermove',e=>{if(!canvasPan||e.pointerId!==canvasPan.id)return;const p=canvasPan;p.viewport.scrollLeft=p.left+p.x-e.clientX;p.viewport.scrollTop=p.top+p.y-e.clientY;e.preventDefault();e.stopImmediatePropagation();},true);
for(const type of ['pointerup','pointercancel'])document.addEventListener(type,e=>{if(canvasPan?.id===e.pointerId){canvasPan=null;e.stopImmediatePropagation();}},true);
async function prepareStudioImage(file){
 const url=URL.createObjectURL(file),image=new Image();
 try{
  image.src=url;await image.decode();
  const w=image.naturalWidth,h=image.naturalHeight;
  if(!w||!h)throw new Error('Imagem sem dimensões.');
  if(['image/png','image/jpeg'].includes(file.type)&&file.size<=8*1024*1024&&w*h<=20000000)return file;
  const scale=Math.min(1,3000/Math.max(w,h)),canvas=document.createElement('canvas');
  canvas.width=Math.max(1,Math.round(w*scale));canvas.height=Math.max(1,Math.round(h*scale));
  canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);
  const mime=file.type==='image/jpeg'?'image/jpeg':'image/png';
  const blob=await new Promise(resolve=>canvas.toBlob(resolve,mime,.9));
  canvas.width=canvas.height=1;
  if(!blob||blob.size>8*1024*1024)throw new Error('A imagem preparada excede 8 MB.');
  return new File([blob],file.name.replace(/\.[^.]+$/,'')+(mime==='image/png'?'.png':'.jpg'),{type:mime});
 }catch(error){throw new Error('Não foi possível preparar a imagem. Escolha PNG, JPG ou WebP na galeria. '+error.message);}
 finally{URL.revokeObjectURL(url);}
}

