function tagDialog(){
 const d=S.data.template.document,cuts=pieceCuts(d),source=tagAt(d,{areaId:S.pasteArea||S.face,layerId:S.selected});if(!source)return;
 const modal=document.createElement('dialog');modal.className='studio-product-dialog';modal.setAttribute('aria-labelledby','studio-tag-title');
 modal.innerHTML=`<form><h2 id="studio-tag-title">Adicionar peça ao mesmo arquivo</h2><p>Crie outros modelos com artes diferentes. Cada peça mantém seu recorte e suas camadas independentes.</p><label>Usar o molde da<select name="source">${cuts.map((p,i)=>`<option value="${esc(p.id)}" ${p.id===source.id?'selected':''}>Peça ${i+1} · ${p.w.toFixed(1)} mm</option>`).join('')}</select></label><label>Começar com<select name="mode"><option value="blank">Somente molde e bases · para outra arte</option><option value="copy">Copiar a arte e os textos · editar separadamente</option></select></label><p class="studio-hint">A nova peça fica ao lado, com 5 mm de espaço. Se faltar largura, usa outra posição livre no A4. O tamanho original é mantido. O PDF inclui todas as peças; Otimizar folha repete o conjunto.</p><p data-tag-status role="status"></p><div class="manage-actions"><button type="button" data-tag-cancel>Cancelar</button><button type="submit" class="btn-primary">Criar peça</button></div></form>`;
 modal.querySelector('[data-tag-cancel]').onclick=()=>modal.close();modal.onclose=()=>modal.remove();
 modal.querySelector('form').onsubmit=e=>{e.preventDefault();try{const form=new FormData(e.target),result=addTag(S.data.template.document,{sourceId:form.get('source'),mode:form.get('mode')});S.data.template.document=result.document;S.faces=[result.areaId];S.face=result.areaId;S.pasteArea=result.areaId;S.areaTemplate=S.data.template.id;selectElements([]);S.tool='layers';dirty();modal.close();render();openPanel('assets');feedback(result.count+' peças independentes no mesmo arquivo. Nova tag '+(result.wrapped?'em outra posição livre.':'ao lado.')+' Selecione uma arte para aplicar; Ctrl+Z desfaz.');}catch(error){modal.querySelector('[data-tag-status]').textContent=error.message;}};
 document.body.append(modal);modal.showModal();
}
function showImageMenu(x,y){
 closeImageMenu();const l=current();if(!l)return;const menu=document.createElement('div');menu.id='studio-image-menu';menu.setAttribute('role','menu');menu.setAttribute('aria-label',l.asset?'Ações da imagem':l.kind?'Ações da forma ou linha':'Ações do texto');
 const actions=[...(S.pasteArea?[['select-context-area','Selecionar esta área'],...(S.clipboardPacket?[['paste-element','Colar nesta área · Ctrl+V']]:[])]:[]),['copy-element','Copiar · Ctrl+C'],...(l.asset?[['aspect-lock',(l.keepRatio!==false?'✓ ':'')+'Fixar proporções'],['image-color','Escolher cor'],['ai-edit','Editar com IA'],['flip-horizontal','Inverter horizontal'],['flip-vertical','Inverter vertical']]:[]),['rotate-left','Girar −90°'],['rotate-right','Girar +90°'],...(l.asset?[['crop-image','Recortar']]:[]),['duplicate-image','Duplicar'],['raise-image','Trazer à frente'],['lower-image','Enviar ao fundo'],['open-properties','Dimensões e transparência'],['lock-layer',l.locked?'Desbloquear':'Bloquear'],['remove-layer','Excluir']];
 menu.innerHTML=actions.map(([action,label])=>`<button type="button" role="menuitem" data-studio="${action}" ${l.locked&&!['lock-layer','open-properties','select-context-area','paste-element'].includes(action)?'disabled':''}>${label}</button>`).join('');document.body.append(menu);
 menu.style.left=Math.max(8,Math.min(x,innerWidth-menu.offsetWidth-8))+'px';menu.style.top=Math.max(8,Math.min(y,innerHeight-menu.offsetHeight-8))+'px';menu.querySelector('button:not(:disabled)')?.focus({preventScroll:true});
 menu.addEventListener('click',()=>queueMicrotask(closeImageMenu));menu.addEventListener('keydown',e=>{const buttons=[...menu.querySelectorAll('button:not(:disabled)')],i=buttons.indexOf(document.activeElement);if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();buttons[(i+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus();}if(e.key==='Escape'){e.preventDefault();e.stopPropagation();closeImageMenu();focusSheet();}});
}
document.addEventListener('pointerdown',e=>{if(!e.target.closest('#studio-image-menu'))closeImageMenu();},true);
window.addEventListener('resize',closeImageMenu);document.addEventListener('scroll',closeImageMenu,true);
function imageColorDialog(){
 const layer=current();if(!layer?.asset||layer.locked)return;
 const modal=document.createElement('dialog');modal.className='studio-color-dialog';modal.innerHTML='<h3>Cor da imagem</h3><p>Substitui todas as cores por uma cor única, mantendo a transparência. A imagem original continua disponível em Artes. Ctrl+Z desfaz.</p><label>Escolher cor <input type="color" value="#bd4f74"></label><div class="manage-actions"><button data-cancel>Cancelar</button><button data-apply>Aplicar cor</button></div>';
 modal.querySelector('[data-cancel]').onclick=()=>modal.close();modal.querySelector('[data-apply]').onclick=()=>{const color=modal.querySelector('input').value;modal.close();busy(async()=>{const response=await fetch('/api/admin/studio/assets/'+layer.asset);if(!response.ok)throw new Error('Não foi possível carregar a imagem.');const bitmap=await createImageBitmap(await response.blob());try{const canvas=document.createElement('canvas');canvas.width=bitmap.width;canvas.height=bitmap.height;const ctx=canvas.getContext('2d');ctx.drawImage(bitmap,0,0);ctx.globalCompositeOperation='source-in';ctx.fillStyle=color;ctx.fillRect(0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw new Error('Não foi possível aplicar a cor.');const form=new FormData();form.set('file',new File([blob],'arte-cor-'+color.slice(1)+'.png',{type:'image/png'}));const result=await request('templates/'+S.data.template.id+'/assets',{method:'POST',body:form});S.data.assets=result.assets;layer.asset=result.asset_id;dirty();properties();preview();feedback('Cor aplicada. Ctrl+Z desfaz.');}finally{bitmap.close();}});};modal.onclose=()=>modal.remove();document.body.append(modal);modal.showModal();
}

function openAIDialog(edit=false){
 if(S.busy||!S.data)return;const templateId=S.data.template.id,layer=current(),layerId=layer?.asset&&!layer.locked&&selectionIds().length===1?layer.id:null,areas=[...selectedAreas()];
 if(edit&&!layerId){feedback('Selecione uma imagem desbloqueada para editar com IA.',true);return;}
 const sameTemplate=()=>{if(S.data?.template.id!==templateId)throw new Error('Reabra o molde original para adicionar a imagem.');};
 showAIImageDialog({request,templateId,assets:S.data.assets.map(a=>({...a})),selectedAsset:layer?.asset,edit,prepareImage:prepareStudioImage,onSave:async()=>{sameTemplate();const result=await request('templates/'+templateId);S.data.assets=result.assets;render();},onAdd:async id=>{sameTemplate();await applyAsset(id,areas);render();feedback('Arte criada com IA e adicionada à área selecionada.');},onReplace:layerId?async id=>{sameTemplate();const target=layers().find(l=>l.id===layerId);if(!target||target.locked)throw new Error('A imagem original não está disponível para substituição.');target.asset=id;delete target.crop;dirty();properties();preview();render();feedback('Imagem substituída. Ctrl+Z desfaz.');}:null}).catch(error=>feedback(error.message,true));
}

function lineControls(){
 const el=document.querySelector('#studio-line-controls');if(!el||!S.data)return;const l=current(),path=l?.kind?l:null,value=path?(isAutomaticCut(path)?automaticCutStyle(path).stroke:path.stroke):S.drawStroke,min=path&&isAutomaticCut(path) ? .18 : .1;
 el.innerHTML='<h3>Espessura da linha</h3>'+select('Linha ou contorno','draw-layer',option('','Novas linhas e curvas',path?.id||'')+(S.data.template.document.paths||[]).map((p,i)=>option(p.id,p.label||({line:'Linha',curve:'Curva',rect:'Retângulo',ellipse:'Círculo',polygon:'Contorno'}[p.kind]||'Forma')+' '+(i+1),path?.id)).join(''))+field('Espessura (mm)','draw-stroke',value,'number','min="'+min+'" max="3" step="0.01" '+(path?.locked?'disabled':''))+field('Ajustar espessura','draw-stroke',value,'range','min="'+min+'" max="3" step="0.01" '+(path?.locked?'disabled':''))+'<p class="studio-hint">'+(path?(path.locked?'Desbloqueie esta camada para alterar a linha.':'Aplica à linha selecionada, com a mesma espessura no PDF.'):'Selecione uma linha na folha ou na lista. Sem seleção, define a espessura das próximas linhas e curvas.')+'</p>';
}
document.addEventListener('change',e=>{if(e.target.dataset.studioInput==='draw-stroke'){properties();preview();}});

document.addEventListener('click',e=>{if(e.target.closest('.studio-menu-content button')){const menu=e.target.closest('.studio-menu');if(menu)menu.open=false;}else if(!e.target.closest('.studio-menu'))document.querySelectorAll('.studio-menu[open]').forEach(menu=>menu.open=false);});

document.addEventListener('error',e=>{if(e.target.matches?.('.studio-card-preview img')){e.target.hidden=true;e.target.parentElement.querySelector('.studio-preview-fallback').hidden=false;}},true);

function newClassifiedStructure(structure){const proposed=classifyTemplate({structure,title:STRUCTURES[structure].label}),dialog=document.createElement('dialog');dialog.className='studio-product-dialog';dialog.setAttribute('aria-label','Criar molde classificado');dialog.innerHTML=`<form><h2>Criar novo molde</h2><p>Defina a classificação antes de abrir o Estúdio. Tipo e tema serão cadastrados na mesma lista usada pelos produtos.</p><label>Nome do molde *<input name="title" required minlength="3" maxlength="160" value="${esc(STRUCTURES[structure].label)}"></label><label>Tipo de molde *<select name="family" required><option value="">Selecione</option>${Object.entries(MOLD_FAMILIES).filter(([k])=>k!=='other'&&(proposed.family==='other'||k===proposed.family)).map(([k,v])=>option(k,v,proposed.family)).join('')}</select></label><label>Tema *<input name="theme" required minlength="2" maxlength="80" placeholder="Ex.: Safari Baby"></label><p role="status"></p><div class="manage-actions"><button type="button" data-cancel>Cancelar</button><button class="btn-primary" type="submit">Criar e abrir</button></div></form>`;dialog.querySelector('[data-cancel]').onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();const form=new FormData(e.target),button=e.target.querySelector('[type=submit]');button.disabled=true;try{const document={...newDocument(structure),catalog:{...proposed,family:form.get('family')}};const result=await request('templates',{method:'POST',body:JSON.stringify({title:form.get('title'),theme:form.get('theme'),document,classification_required:true})});S.list=null;S.error='';dialog.close();location.hash='/admin/estudio/'+result.template.id;}catch(error){dialog.querySelector('[role=status]').textContent=error.message;button.disabled=false;}};document.body.append(dialog);dialog.showModal();}

document.addEventListener('click',e=>{const button=e.target.closest('[data-library-model]');if(!button)return;const group=button.closest('[data-library-type]'),type=group.dataset.libraryType,models=groupLibraryModels(filterTemplates(S.list||[],studioFilters)),model=models.find(m=>m.type===type&&m.key===button.dataset.libraryModel);if(!model)return;libraryViewState.selected[type]=model.key;libraryViewState.typeOpen=type;group.querySelectorAll('[data-library-model]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));group.querySelector('[data-library-artwork]').innerHTML=renderLibraryArtwork(model,libraryArtworkCard);});
document.addEventListener('toggle',e=>{const group=e.target;if(!group.matches?.('.studio-type-group'))return;if(group.open){libraryViewState.typeOpen=group.dataset.libraryType;document.querySelectorAll('.studio-type-group[open]').forEach(other=>{if(other!==group)other.open=false;});}else if(libraryViewState.typeOpen===group.dataset.libraryType)libraryViewState.typeOpen=null;},true);

function preferredArtArea(d){const areas=documentAreas(d);return areas.find(a=>a.id.startsWith('shape-')&&d.paths?.some(p=>'shape-'+p.id===a.id&&(p.editableFace||p.usage==='art'&&p.fill)))||areas.find(a=>a.id!=='page')||areas[0];}

function applyCachepotEdge(){try{S.data.template.document=setCachepotStandardEdge(S.data.template.document,{style:document.querySelector('#studio-cachepot-edge-style').value,count:Number(document.querySelector('#studio-cachepot-edge-count').value)});dirty();properties();preview();feedback('Borda padronizada com altura automática. Ctrl+Z desfaz.');}catch(error){feedback(error.message,true);}}
document.addEventListener('change',e=>{if(!['studio-cachepot-edge-style','studio-cachepot-edge-count'].includes(e.target.id))return;applyCachepotEdge();});

document.addEventListener('toggle',e=>{const menu=e.target;if(!menu.matches?.('.studio-menu')||!menu.open)return;document.querySelectorAll('.studio-menu[open]').forEach(other=>{if(other!==menu)other.open=false;});},true);
